def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        bid = DAILY_SALARY * 0.25
        if hp <= 2 or no_water >= 2:
            bid = DAILY_SALARY * 0.6
        return min(budget, max(0, bid))

    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) > DAILY_SALARY * 6:
            rich_aggressive += 1

    player_count = len(alive) + 1
    approx_winners = max(1, int(supply // WATER_REQ))
    scarcity = approx_winners < player_count
    very_scarce = approx_winners <= max(1, player_count // 2)

    base = DAILY_SALARY * 0.42
    if not scarcity:
        base = DAILY_SALARY * 0.28
    elif very_scarce:
        base = DAILY_SALARY * 0.58

    if hp <= 2 or no_water >= 2:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4 or no_water >= 1:
        base = max(base, DAILY_SALARY * 0.68)

    if desperate_count >= max(1, len(alive) // 2):
        base += 8
    if rich_aggressive >= max(1, len(alive) // 2):
        base += 5

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if hp > 4 and no_water == 0 and highest_prev >= DAILY_SALARY * 0.9:
            base = min(base, DAILY_SALARY * 0.35)
        else:
            target = max(avg_prev + 1.0, highest_prev + 1.5)
            if scarcity:
                base = max(base, target)
            else:
                base = max(base, min(target, DAILY_SALARY * 0.55))

    reserve_days = 3 if hp > 3 else 1
    max_affordable = max(0, budget - reserve_days * DAILY_SALARY * 0.25)
    bid = min(base, budget)
    if max_affordable > 0:
        bid = min(bid, max_affordable)

    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.9))

    if bid < 0:
        bid = 0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents, take minimal safe bid.
    if not alive_opponents:
        bid = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, float(bid))

    # Read yesterday's bids from previous_trace.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Determine opponent pressure.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0.0

    # Base strategy: react to revealed aggressiveness.
    # If opponents were bidding very high yesterday, we must contest water.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Our urgency increases if low hp or already several no-water days.
        urgency = 0.0
        if hp <= 2.5:
            urgency += 0.35
        if no_water_days >= 1:
            urgency += 0.25
        if no_water_days >= 2:
            urgency += 0.25
        # Bid strong but not maximal.
        target = DAILY_SALARY * (0.45 + urgency)
        bid = min(budget, target)
    else:
        # If they were not aggressive, conserve budget and bid around a moderate level.
        # Use their average as a signal.
        target = max(DAILY_SALARY * 0.35, avg_prev_bid * 0.9 + 5.0)
        # Adjust for our health: lower hp => higher bid.
        if hp <= 2.5:
            target = max(target, DAILY_SALARY * 0.75)
        elif hp <= 4.0:
            target = max(target, DAILY_SALARY * 0.55)
        bid = min(budget, target)

    # Supply-aware adjustment: if supply is scarce, slightly increase bid.
    # Normalize supply within [MIN_SUPPLY, MAX_SUPPLY].
    denom = float(MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) != 0 else 1.0
    scarcity = (float(MAX_SUPPLY) - supply) / denom
    if scarcity > 0.0:
        bid = bid * (1.0 + 0.15 * min(1.0, scarcity))

    # Final clamps.
    bid = float(bid)
    if bid < 0.0:
        bid = 0.0
    if budget <= 0.0:
        return 0.0
    if bid > budget:
        bid = budget

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive_opps:
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    hp = my_status['hp']
    budget = my_status['budget']
    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)
    base_bid = DAILY_SALARY * 0.5
    if prev_bids:
        max_prev = max(prev_bids)
        base_bid = max_prev + 1.0
    if hp <= 2:
        bid = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 4:
        bid = min(budget, max(base_bid, DAILY_SALARY * 0.6))
    else:
        bid = min(budget, max(base_bid, DAILY_SALARY * 0.4))
    return min(bid, budget)
